training_js = r'''
const TRAINING_MIN_RUNS=2,TRAINING_TARGET=70;
const trainingStats=read(STORE.training,{schemaVersion:1,modes:{}});
if(!trainingStats.modes)trainingStats.modes={};
['challenge','hunt','memory'].forEach(mode=>{if(!trainingStats.modes[mode])trainingStats.modes[mode]={}});
function activitySetLabel(id){if(id==='all')return'Alle Kategorien';if(id==='favorites')return'Favoriten';return categories[id]?.label||id}
function trainingBucket(mode,cat){const root=trainingStats.modes[mode]||(trainingStats.modes[mode]={});if(!root[cat])root[cat]=mode==='memory'?{completedRuns:0,pairs:0,moves:0,points:0,lastEfficiency:0,bestEfficiency:0,lastAt:null}:{completedRuns:0,correct:0,wrong:0,lastAccuracy:0,bestAccuracy:0,lastAt:null,retries:0};return root[cat]}
function evidenceSummary(){let accuracyRuns=0,correct=0,wrong=0,memoryRuns=0;['challenge','hunt'].forEach(mode=>Object.values(trainingStats.modes[mode]||{}).forEach(b=>{accuracyRuns+=Number(b.completedRuns)||0;correct+=Number(b.correct)||0;wrong+=Number(b.wrong)||0}));Object.values(trainingStats.modes.memory||{}).forEach(b=>memoryRuns+=Number(b.completedRuns)||0);const attempts=correct+wrong;return{accuracyRuns,correct,wrong,attempts,accuracy:attempts?Math.round(correct/attempts*100):0,memoryRuns}}
function syncA7Progress(){const s=evidenceSummary();localStorage.setItem(STORE.progress,JSON.stringify({schemaVersion:1,completed:s.accuracyRuns>=TRAINING_MIN_RUNS,completedRuns:s.accuracyRuns,accuracy:s.accuracy,target:TRAINING_TARGET,targetReached:s.attempts>0&&s.accuracy>=TRAINING_TARGET,pdfReady:s.accuracyRuns>=TRAINING_MIN_RUNS,updatedAt:new Date().toISOString()}))}
function saveTrainingStats(){trainingStats.schemaVersion=1;trainingStats.updatedAt=new Date().toISOString();localStorage.setItem(STORE.training,JSON.stringify(trainingStats));syncA7Progress()}
function recordAccuracyRun(mode,cat,correct,wrong,extra={}){const b=trainingBucket(mode,cat),total=correct+wrong,accuracy=total?Math.round(correct/total*100):0;b.completedRuns=(Number(b.completedRuns)||0)+1;b.correct=(Number(b.correct)||0)+correct;b.wrong=(Number(b.wrong)||0)+wrong;b.lastAccuracy=accuracy;b.bestAccuracy=Math.max(Number(b.bestAccuracy)||0,accuracy);b.lastAt=new Date().toISOString();b.retries=(Number(b.retries)||0)+(Number(extra.retries)||0);saveTrainingStats();if($('#evidenceRows'))renderEvidence()}
function recordMemoryRun(cat,diff,pairs,moves,points,elapsed){const b=trainingBucket('memory',cat),eff=moves?Math.min(100,Math.round(pairs/moves*100)):100;b.completedRuns=(Number(b.completedRuns)||0)+1;b.pairs=(Number(b.pairs)||0)+pairs;b.moves=(Number(b.moves)||0)+moves;b.points=(Number(b.points)||0)+points;b.lastEfficiency=eff;b.bestEfficiency=Math.max(Number(b.bestEfficiency)||0,eff);b.lastDiff=diff;b.lastElapsed=Math.round(elapsed);b.lastAt=new Date().toISOString();saveTrainingStats();if($('#evidenceRows'))renderEvidence()}
function evidenceRowsData(){const ids=['all',...Object.keys(categories)],hasFav=['challenge','hunt','memory'].some(mode=>trainingStats.modes[mode]?.favorites);if(hasFav)ids.push('favorites');return ids.map(id=>{const buckets=['challenge','hunt'].map(mode=>trainingStats.modes[mode]?.[id]).filter(Boolean),memory=trainingStats.modes.memory?.[id],accuracyRuns=buckets.reduce((s,b)=>s+(Number(b.completedRuns)||0),0),correct=buckets.reduce((s,b)=>s+(Number(b.correct)||0),0),wrong=buckets.reduce((s,b)=>s+(Number(b.wrong)||0),0),attempts=correct+wrong,latest=buckets.filter(b=>b.lastAt).sort((a,b)=>String(b.lastAt).localeCompare(String(a.lastAt)))[0],best=Math.max(0,...buckets.map(b=>Number(b.bestAccuracy)||0));return{id,label:activitySetLabel(id),accuracyRuns,accuracy:attempts?Math.round(correct/attempts*100):0,last:latest?Number(latest.lastAccuracy)||0:0,best,memoryRuns:Number(memory?.completedRuns)||0}})}
function renderEvidence(){const s=evidenceSummary(),rows=evidenceRowsData().filter(r=>r.accuracyRuns||r.memoryRuns),host=$('#evidenceRows'),button=$('#downloadEvidencePdf');if(!host||!button)return;$('#evidenceRuns').textContent=s.accuracyRuns;$('#evidenceAccuracy').textContent=s.attempts?`${s.accuracy} %`:'–';$('#evidenceMemoryRuns').textContent=s.memoryRuns;$('#evidenceStatus').textContent=s.accuracyRuns>=TRAINING_MIN_RUNS?'PDF bereit ✓':`${s.accuracyRuns} / ${TRAINING_MIN_RUNS} Runden`;host.innerHTML=rows.length?rows.map(r=>`<div class="evidence-row"><div class="set-name">${escapeHtml(r.label)}</div><div class="evidence-cell"><span>Runden</span><strong>${r.accuracyRuns}</strong></div><div class="evidence-cell"><span>Genauigkeit</span><strong>${r.accuracyRuns?r.accuracy+' %':'–'}</strong></div><div class="evidence-cell"><span>Letzte / Best</span><strong>${r.accuracyRuns?r.last+' / '+r.best+' %':'–'}</strong></div><div class="evidence-cell"><span>Memory</span><strong>${r.memoryRuns}</strong></div></div>`).join(''):'<div class="evidence-empty">Noch keine abgeschlossene Trainingsrunde. Starte eine Challenge, Fehlerjagd oder ein Memory.</div>';button.disabled=s.accuracyRuns<TRAINING_MIN_RUNS;const remaining=Math.max(0,TRAINING_MIN_RUNS-s.accuracyRuns);$('#evidenceHint').textContent=remaining?`Noch ${remaining} abgeschlossene Runde${remaining===1?'':'n'} bis zur PDF.`:`PDF freigeschaltet · aktuelle Genauigkeit ${s.accuracy} % · Ziel ${TRAINING_TARGET} %. `;syncA7Progress()}
function downloadTrainingPdf(){const s=evidenceSummary();if(s.accuracyRuns<TRAINING_MIN_RUNS){alert('Beende zuerst mindestens zwei Runden in Challenge oder Fehlerjagd.');return}const student=typeof requireStudentName==='function'?requireStudentName():'';if(!student)return;const rows=evidenceRowsData().filter(r=>r.accuracyRuns||r.memoryRuns),canvas=document.createElement('canvas');canvas.width=1200;canvas.height=850;const ctx=canvas.getContext('2d'),g=ctx.createLinearGradient(0,0,1200,850);g.addColorStop(0,'#0f172a');g.addColorStop(1,'#1e3a5f');ctx.fillStyle=g;ctx.fillRect(0,0,1200,850);ctx.strokeStyle='#38bdf8';ctx.lineWidth=6;ctx.strokeRect(30,30,1140,790);ctx.textAlign='center';ctx.fillStyle='#7dd3fc';ctx.font='800 20px sans-serif';ctx.fillText('INFORMATIK B25 – A7',600,88);ctx.fillStyle='#fff';ctx.font='800 36px sans-serif';ctx.fillText('TRAININGSNACHWEIS TASTENKÜRZEL',600,145);ctx.fillStyle='#94a3b8';ctx.font='500 17px sans-serif';ctx.fillText('Challenge + Fehlerjagd = Genauigkeit · Memory separat',600,180);ctx.fillStyle='rgba(56,189,248,.13)';ctx.strokeStyle='#38bdf8';ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(235,205,730,64,16);ctx.fill();ctx.stroke();ctx.fillStyle='#bae6fd';ctx.font='800 27px sans-serif';ctx.fillText(student,600,246);ctx.fillStyle=s.accuracy>=TRAINING_TARGET?'#34d399':'#fbbf24';ctx.font='800 25px sans-serif';ctx.fillText(`${s.accuracyRuns} Runden · ${s.accuracy} % Genauigkeit · Ziel ${TRAINING_TARGET} %`,600,315);ctx.fillStyle='#94a3b8';ctx.font='500 15px sans-serif';ctx.fillText(s.accuracy>=TRAINING_TARGET?'Zielgenauigkeit erreicht ✓':'Zielgenauigkeit noch nicht erreicht',600,343);ctx.fillStyle='rgba(15,23,42,.72)';ctx.beginPath();ctx.roundRect(85,375,1030,355,20);ctx.fill();ctx.textAlign='left';ctx.fillStyle='#94a3b8';ctx.font='700 14px sans-serif';ctx.fillText('SET',125,410);ctx.fillText('RUNDEN',525,410);ctx.fillText('GENAUIGKEIT',675,410);ctx.fillText('BEST',855,410);ctx.fillText('MEMORY',1000,410);let y=450;rows.slice(0,7).forEach(r=>{ctx.fillStyle='#e2e8f0';ctx.font='700 17px sans-serif';ctx.fillText(r.label,125,y);ctx.fillStyle='#cbd5e1';ctx.font='600 16px sans-serif';ctx.fillText(String(r.accuracyRuns),540,y);ctx.fillStyle=r.accuracyRuns?(r.accuracy>=TRAINING_TARGET?'#34d399':'#fbbf24'):'#64748b';ctx.fillText(r.accuracyRuns?r.accuracy+' %':'–',700,y);ctx.fillStyle='#cbd5e1';ctx.fillText(r.accuracyRuns?r.best+' %':'–',870,y);ctx.fillText(String(r.memoryRuns),1025,y);y+=40});ctx.textAlign='center';ctx.fillStyle='#94a3b8';ctx.font='500 14px sans-serif';ctx.fillText('PDF-Freigabe nach mindestens 2 abgeschlossenen Challenge-/Fehlerjagd-Runden · '+new Date().toLocaleDateString('de-CH'),600,790);function make(){const pdf=new window.jspdf.jsPDF({orientation:'landscape',unit:'mm',format:[297,210]});pdf.addImage(canvas.toDataURL('image/png'),'PNG',0,0,297,210);const safe=typeof sanitizeStudentNameForFileName==='function'?sanitizeStudentNameForFileName(student):student.replace(/[^a-zA-Z0-9]/g,'_');pdf.save('A7_Trainingsnachweis_'+safe+'.pdf')}if(window.jspdf)make();else{const script=document.createElement('script');script.src='../tk/vendor/jspdf.umd.min.js';script.onload=make;document.head.appendChild(script)}}
'''
